from __future__ import annotations
import argparse,csv,hashlib,io,sys
from datetime import datetime
from decimal import Decimal,InvalidOperation
from pathlib import Path
from urllib.parse import parse_qs,urlparse
from urllib.request import Request,urlopen

ROOT=Path(__file__).resolve().parents[2]; OUT=ROOT/"deliverables"
TX=["transaction_id","date","account","category","description","amount","currency","status","source","source_version","amount_status"]
BU=["period","category","budget_amount","currency","owner","review_rule","source","source_version"]
RE=["date","source","metric","value","currency","source_version"]
SCHEMAS={"transactions":TX,"budget":BU,"revenue":RE}
class BriefError(Exception): pass

def clear_outputs():
    for p in (OUT/"normalized/transactions.csv",OUT/"normalized/budget.csv",OUT/"normalized/revenue.csv",OUT/"report.md"): p.unlink(missing_ok=True)

def sheet_info(url):
    q=parse_qs(urlparse(url).query); parts=urlparse(url).path.split("/")
    try: sid=parts[parts.index("d")+1]
    except (ValueError,IndexError): sid="unknown"
    return sid,q.get("gid",["0"])[0]

def fetch(url):
    sid,gid=sheet_info(url); target=f"https://docs.google.com/spreadsheets/d/{sid}/export?format=csv&gid={gid}"
    try:
        with urlopen(Request(target,headers={"User-Agent":"daily-financial-health-brief/1.0"}),timeout=20) as r: raw=r.read()
    except Exception as e: raise BriefError(f"source fetch failed for {url}: {e}") from e
    try: rows=list(csv.DictReader(io.StringIO(raw.decode("utf-8-sig"))))
    except Exception as e: raise BriefError(f"CSV parse failed for {url}: {e}") from e
    if not rows: raise BriefError(f"source has no data rows: {url}")
    return sid,gid,rows,hashlib.sha256(raw).hexdigest()

def role(rows):
    fields=set(rows[0])
    for name,schema in SCHEMAS.items():
        if set(schema).issubset(fields): return name
    raise BriefError(f"unrecognized source schema: {sorted(fields)}")

def dec(value,field,row):
    if value=="": return ""
    try: return Decimal(value)
    except InvalidOperation as e: raise BriefError(f"invalid {field} value {value!r} in row {row}") from e

def material(variance,baseline):
    v,b=abs(Decimal(variance)),abs(Decimal(baseline))
    return v>Decimal("500") if b==0 else v>Decimal("500") and v>b*Decimal("0.10")

def write_csv(name,rows):
    path=OUT/"normalized"/f"{name}.csv"; path.parent.mkdir(parents=True,exist_ok=True)
    with path.open("w",newline="",encoding="utf-8") as f:
        w=csv.DictWriter(f,fieldnames=SCHEMAS[name],lineterminator="\n"); w.writeheader()
        for row in rows: w.writerow({key:row.get(key,"") for key in SCHEMAS[name]})

def run(args):
    clear_outputs()
    if not args.prior_business_date or not args.revenue_snapshot_date:
        raise BriefError("clarification required: prior business date and revenue snapshot date are explicit parameters")
    by={}; metadata=[]
    for url in (args.transaction_url,args.budget_url,args.revenue_url):
        sid,gid,rows,digest=fetch(url); name=role(rows)
        if name in by: raise BriefError(f"duplicate source role {name}")
        by[name]=rows; metadata.append((name,url,sid,gid,len(rows),digest,datetime.now().astimezone().isoformat()))
    for name,rows in by.items(): write_csv(name,rows)
    raise BriefError("clarification required: configure status mappings, sign conventions, revenue metric selection, and source completeness policy before publishing report")

def main():
    p=argparse.ArgumentParser(); p.add_argument("--reporting-date",required=True); p.add_argument("--prior-business-date",required=True); p.add_argument("--revenue-snapshot-date",required=True)
    p.add_argument("--transaction-url",required=True); p.add_argument("--budget-url",required=True); p.add_argument("--revenue-url",required=True)
    try: run(p.parse_args())
    except BriefError as e: clear_outputs(); print(f"ERROR: {e}",file=sys.stderr); return 2
    return 0
if __name__=="__main__": raise SystemExit(main())

